## `app.js`
```javascript
const STORAGE_KEY = "daily-desk:v1";

const $ = (sel) => document.querySelector(sel);

const nowEl = $("#now");
const lastSavedEl = $("#lastSaved");

const taskForm = $("#taskForm");
const taskInput = $("#taskInput");
const taskList = $("#taskList");
const taskStats = $("#taskStats");
const clearCompletedBtn = $("#clearCompletedBtn");
const clearAllTasksBtn = $("#clearAllTasksBtn");

const noteForm = $("#noteForm");
const noteInput = $("#noteInput");
const noteList = $("#noteList");
const clearNotesBtn = $("#clearNotesBtn");

let state = loadState();
let taskFilter = "all";

// ----- Date helpers (local time) -----
function formatLocal(isoString) {
  const d = new Date(isoString);
  return d.toLocaleString();
}

function tickClock() {
  nowEl.textContent = new Date().toLocaleString();
}
tickClock();
setInterval(tickClock, 1000);

// ----- Storage -----
function loadState() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) {
      return {
        tasks: [],
        notes: [],
        lastSavedAt: null
      };
    }
    const parsed = JSON.parse(raw);
    return {
      tasks: Array.isArray(parsed.tasks) ? parsed.tasks : [],
      notes: Array.isArray(parsed.notes) ? parsed.notes : [],
      lastSavedAt: parsed.lastSavedAt ?? null
    };
  } catch {
    return { tasks: [], notes: [], lastSavedAt: null };
  }
}

function saveState() {
  state.lastSavedAt = new Date().toISOString();
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  renderLastSaved();
}

function renderLastSaved() {
  if (!state.lastSavedAt) {
    lastSavedEl.textContent = "Not saved yet";
    return;
  }
  lastSavedEl.textContent = `Saved: ${formatLocal(state.lastSavedAt)}`;
}

// ----- Tasks -----
function makeId() {
  return Math.random().toString(16).slice(2) + "-" + Date.now().toString(16);
}

function addTask(title) {
  const task = {
    id: makeId(),
    title: title.trim(),
    done: false,
    createdAt: new Date().toISOString(),
    completedAt: null
  };
  state.tasks.unshift(task);
  saveState();
  render();
}

function toggleTask(id) {
  const t = state.tasks.find(x => x.id === id);
  if (!t) return;
  t.done = !t.done;
  t.completedAt = t.done ? new Date().toISOString() : null;
  saveState();
  render();
}

function deleteTask(id) {
  state.tasks = state.tasks.filter(x => x.id !== id);
  saveState();
  render();
}

function clearCompleted() {
  state.tasks = state.tasks.filter(t => !t.done);
  saveState();
  render();
}

function clearAllTasks() {
  state.tasks = [];
  saveState();
  render();
}

function filteredTasks() {
  if (taskFilter === "active") return state.tasks.filter(t => !t.done);
  if (taskFilter === "done") return state.tasks.filter(t => t.done);
  return state.tasks;
}

function renderTasks() {
  const tasks = filteredTasks();
  taskList.innerHTML = "";

  if (tasks.length === 0) {
    const li = document.createElement("li");
    li.className = "hint";
    li.textContent = taskFilter === "all"
      ? "No tasks yet. Add one above."
      : `No ${taskFilter} tasks.`;
    taskList.appendChild(li);
    return;
  }

  for (const t of tasks) {
    const li = document.createElement("li");
    li.className = "task" + (t.done ? " done" : "");
    li.dataset.id = t.id;

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.checked = t.done;
    checkbox.ariaLabel = "Mark task as done";
    checkbox.addEventListener("change", () => toggleTask(t.id));

    const main = document.createElement("div");

    const title = document.createElement("div");
    title.className = "title";
    title.textContent = t.title;

    const meta = document.createElement("div");
    meta.className = "meta";
    const created = document.createElement("span");
    created.textContent = `Created: ${formatLocal(t.createdAt)}`;
    meta.appendChild(created);

    if (t.done && t.completedAt) {
      const completed = document.createElement("span");
      completed.textContent = `Done: ${formatLocal(t.completedAt)}`;
      meta.appendChild(completed);
    }

    main.appendChild(title);
    main.appendChild(meta);

    const del = document.createElement("button");
    del.className = "iconbtn";
    del.title = "Delete task";
    del.textContent = "Del";
    del.addEventListener("click", () => {
      if (confirm("Delete this task?")) deleteTask(t.id);
    });

    li.appendChild(checkbox);
    li.appendChild(main);
    li.appendChild(del);

    taskList.appendChild(li);
  }
}

function renderTaskStats() {
  const total = state.tasks.length;
  const done = state.tasks.filter(t => t.done).length;
  const active = total - done;
  taskStats.textContent = `${total} total • ${active} active • ${done} done`;

  clearCompletedBtn.disabled = done === 0;
  clearAllTasksBtn.disabled = total === 0;
}

// ----- Notes -----
function addNote(text) {
  const note = {
    id: makeId(),
    text: text.trim(),
    createdAt: new Date().toISOString()
  };
  state.notes.unshift(note);
  saveState();
  render();
}

function clearNotes() {
  state.notes = [];
  saveState();
  render();
}

function deleteNote(id) {
  state.notes = state.notes.filter(n => n.id !== id);
  saveState();
  render();
}

function renderNotes() {
  noteList.innerHTML = "";

  if (state.notes.length === 0) {
    const li = document.createElement("li");
    li.className = "hint";
    li.textContent = "No notes yet. Add one above.";
    noteList.appendChild(li);
    return;
  }

  for (const n of state.notes) {
    const li = document.createElement("li");
    li.className = "note";

    const when = document.createElement("div");
    when.className = "when";
    when.textContent = formatLocal(n.createdAt);

    const text = document.createElement("div");
    text.className = "text";
    text.textContent = n.text;

    const row = document.createElement("div");
    row.className = "row";
    row.style.marginTop = "10px";
    row.style.justifyContent = "flex-end";

    const del = document.createElement("button");
    del.className = "btn ghost";
    del.textContent = "Delete";
    del.addEventListener("click", () => {
      if (confirm("Delete this note?")) deleteNote(n.id);
    });

    row.appendChild(del);

    li.appendChild(when);
    li.appendChild(text);
    li.appendChild(row);

    noteList.appendChild(li);
  }

  clearNotesBtn.disabled = state.notes.length === 0;
}

// ----- Filter UI -----
document.querySelectorAll(".seg").forEach(btn => {
  btn.addEventListener("click", () => {
    taskFilter = btn.dataset.filter;
    document.querySelectorAll(".seg").forEach(b => b.classList.toggle("active", b === btn));
    renderTasks();
  });
});

// ----- Events -----
taskForm.addEventListener("submit", (e) => {
  e.preventDefault();
  const title = taskInput.value.trim();
  if (!title) return;
  addTask(title);
  taskInput.value = "";
  taskInput.focus();
});

clearCompletedBtn.addEventListener("click", () => {
  if (confirm("Clear all completed tasks?")) clearCompleted();
});

clearAllTasksBtn.addEventListener("click", () => {
  if (confirm("Clear ALL tasks?")) clearAllTasks();
});

noteForm.addEventListener("submit", (e) => {
  e.preventDefault();
  const text = noteInput.value.trim();
  if (!text) return;
  addNote(text);
  noteInput.value = "";
  noteInput.focus();
});

clearNotesBtn.addEventListener("click", () => {
  if (confirm("Clear ALL notes?")) clearNotes();
});

// ----- Render -----
function render() {
  renderLastSaved();
  renderTaskStats();
  renderTasks();
  renderNotes();
}

render();
```

