## App wiring

### `app/App.tsx` (core state + handlers)
```tsx
import React, { useEffect, useMemo, useRef, useState } from "react";
import { loadAllItems, putItem } from "../db/db";
import { deriveCompletedTodayIds, deriveRecentIds, deriveTodayIds, groupRecentByCreatedDay } from "../model/derive";
import { Item, LastDeleted, Task } from "../model/types";
import { useGlobalKeys } from "./useGlobalKeys";

import { CaptureInput } from "../ui/CaptureInput";
import { TodayList } from "../ui/TodayList";
import { RecentPanel } from "../ui/RecentPanel";
import { ToastUndo } from "../ui/ToastUndo";

const todayKey = () => new Date().toISOString().slice(0,10);
const uid = () => crypto.randomUUID();

export default function App() {
  const [items, setItems] = useState<Item[]>([]);
  const itemsById = useMemo(() => new Map(items.map(i => [i.id, i])), [items]);

  const [captureText, setCaptureText] = useState("");
  const captureRef = useRef<HTMLInputElement>(null);

  const [recentExpanded, setRecentExpanded] = useState(false);
  const [lastDeleted, setLastDeleted] = useState<LastDeleted>(null);

  useEffect(() => { loadAllItems().then(setItems); }, []);

  const tKey = todayKey();
  const now = Date.now();

  const todayIds = useMemo(() => deriveTodayIds(items, tKey), [items, tKey]);
  const completedTodayIds = useMemo(() => deriveCompletedTodayIds(items, tKey), [items, tKey]);
  const recentIds = useMemo(() => deriveRecentIds(items, now, 7), [items, now]);
  const recentGroups = useMemo(() => groupRecentByCreatedDay(itemsById, recentIds), [itemsById, recentIds]);

  useGlobalKeys({
    captureRef,
    clearCapture: () => setCaptureText(""),
    hasCaptureText: () => captureText.trim().length > 0,
    collapsePanels: () => setRecentExpanded(false),
  });

  async function addFromCapture(textRaw: string) {
    const text = textRaw.trim();
    if (!text) return;

    let kind: "task" | "note" = "task";
    let body = text;

    if (text.toLowerCase().startsWith("t:")) { kind = "task"; body = text.slice(2).trim(); }
    if (text.toLowerCase().startsWith("n:")) { kind = "note"; body = text.slice(2).trim(); }
    if (!body) return;

    const base = { id: uid(), text: body, createdAt: Date.now(), deletedAt: null as const };

    const item: Item = kind === "task"
      ? ({ ...base, kind: "task", completedAt: null, pinnedToToday: true } as Task)
      : ({ ...base, kind: "note" } as any);

    setItems(prev => [item, ...prev]);
    await putItem(item);
  }

  async function toggleComplete(id: string) {
    const it = itemsById.get(id);
    if (!it || it.kind !== "task" || it.deletedAt) return;
    const next: Item = { ...it, completedAt: it.completedAt ? null : Date.now() } as Task;
    setItems(prev => prev.map(x => x.id === id ? next : x));
    await putItem(next);
  }

  async function softDelete(id: string) {
    const it = itemsById.get(id);
    if (!it || it.deletedAt) return;
    const next: Item = { ...it, deletedAt: Date.now() };
    setItems(prev => prev.map(x => x.id === id ? next : x));
    await putItem(next);

    setLastDeleted({ id, snapshot: it, expiresAt: Date.now() + 10_000 });
  }

  async function undoDelete() {
    if (!lastDeleted) return;
    if (Date.now() > lastDeleted.expiresAt) { setLastDeleted(null); return; }
    const snap = lastDeleted.snapshot;
    const restored: Item = { ...snap, deletedAt: null };
    setItems(prev => prev.map(x => x.id === restored.id ? restored : x));
    await putItem(restored);
    setLastDeleted(null);
  }

  return (
    <div className="app">
      <CaptureInput
        inputRef={captureRef}
        value={captureText}
        onChange={setCaptureText}
        onSubmit={async () => {
          await addFromCapture(captureText);
          setCaptureText("");
          captureRef.current?.focus();
        }}
        onEscape={() => setCaptureText("")}
      />

      <TodayList
        todayIds={todayIds}
        completedTodayIds={completedTodayIds}
        itemsById={itemsById}
        onToggleComplete={toggleComplete}
        onDelete={softDelete}
      />

      <RecentPanel
        expanded={recentExpanded}
        onToggle={() => setRecentExpanded(v => !v)}
        groups={recentGroups}
        itemsById={itemsById}
        onToggleComplete={toggleComplete}
        onDelete={softDelete} // optional in recent; keep if you want
      />

      <ToastUndo
        visible={!!lastDeleted}
        onUndo={undoDelete}
        onDismiss={() => setLastDeleted(null)}
      />
    </div>
  );
}
```

