import React from "react";

export function CaptureInput(props: {
  inputRef: React.RefObject<HTMLInputElement>;
  value: string;
  onChange: (v: string) => void;
  onSubmit: () => void;
  onEscape: () => void;
}) {
  return (
    <div>
      <input
        ref={props.inputRef}
        value={props.value}
        onChange={(e) => props.onChange(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Enter") {
            e.preventDefault();
            props.onSubmit();
          } else if (e.key === "Escape") {
            e.preventDefault();
            props.onEscape();
          }
        }}
        placeholder="Type a task… (t: task, n: note)"
        aria-label="Capture"
      />
    </div>
  );
}
