## Recent panel: collapsed by default, focus + keydown when expanded

### `ui/RecentPanel.tsx`
```tsx
import React, { useEffect, useRef, useState } from "react";
import { Item } from "../model/types";
import { RecentItemRow } from "./RecentItemRow";

export function RecentPanel(props: {
  expanded: boolean;
  onToggle: () => void;
  groups: Array<[dayKey: string, ids: string[]]>;
  itemsById: Map<string, Item>;
  onToggleComplete: (id: string) => void;
  onDelete: (id: string) => void;
}) {
  const flatIds = props.groups.flatMap(([, ids]) => ids);

  const [focusIndex, setFocusIndex] = useState(0);
  const rowRefs = useRef<Array<HTMLDivElement | null>>([]);

  useEffect(() => {
    if (!props.expanded) return;
    if (flatIds.length === 0) return;
    // Optional: auto-focus first recent item on expand
    setTimeout(() => rowRefs.current[0]?.focus(), 0);
  }, [props.expanded]); // eslint-disable-line

  const focusRow = (i: number) => {
    const clamped = Math.max(0, Math.min(i, flatIds.length - 1));
    setFocusIndex(clamped);
    rowRefs.current[clamped]?.focus();
  };

  return (
    <section aria-label="Recent">
      <button onClick={props.onToggle} aria-expanded={props.expanded}>
        Recent (7 days)
      </button>

      {props.expanded && (
        <div>
          {props.groups.map(([day, ids]) => (
            <div key={day}>
              <h3>{day}</h3>
              <div role="list">
                {ids.map((id) => {
                  const globalIndex = flatIds.indexOf(id); // fine for v1; optimize later
                  const it = props.itemsById.get(id);
                  if (!it) return null;

                  return (
                    <RecentItemRow
                      key={id}
                      ref={(el) => { rowRefs.current[globalIndex] = el; }}
                      item={it}
                      tabIndex={globalIndex === focusIndex ? 0 : -1}
                      onFocus={() => setFocusIndex(globalIndex)}
                      onKeyDown={(e) => {
                        if (e.key === "ArrowDown") { e.preventDefault(); focusRow(globalIndex + 1); }
                        else if (e.key === "ArrowUp") { e.preventDefault(); focusRow(globalIndex - 1); }
                        else if (e.key === " " && it.kind === "task") { e.preventDefault(); props.onToggleComplete(id); }
                        else if (e.key.toLowerCase() === "x") { e.preventDefault(); props.onDelete(id); }
                      }}
                      onToggleComplete={() => it.kind === "task" && props.onToggleComplete(id)}
                    />
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </section>
  );
}
```

