## 4) Stop re-attaching the global key listener every render
If you like passing an object, use the “ref wrapper” approach (Option B). It’s robust and keeps call-sites simple.

```ts
export function useGlobalKeys(opts: GlobalKeyOpts) {
  const optsRef = useRef(opts);
  optsRef.current = opts;

  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      const o = optsRef.current;
      // ...use `o`...
    };

    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, []);
}
```

That’s usually the lowest-friction fix.

