## Data model + derived lists

### `model/types.ts`
```ts
export type ID = string;

export type BaseItem = {
  id: ID;
  kind: "task" | "note";
  text: string;
  createdAt: number;     // epoch ms
  deletedAt: number | null;
};

export type Task = BaseItem & {
  kind: "task";
  completedAt: number | null;
  pinnedToToday?: boolean; // optional for v1
  dueDate?: string | null; // "YYYY-MM-DD" optional
};

export type Note = BaseItem & {
  kind: "note";
};

export type Item = Task | Note;

export type LastDeleted = {
  id: ID;
  snapshot: Item;
  expiresAt: number;
} | null;
```

### `model/derive.ts`
```ts
import { Item, Task } from "./types";

const dayKey = (ms: number) => new Date(ms).toISOString().slice(0, 10);

export function deriveTodayIds(items: Item[], todayKey: string) {
  return items
    .filter((it) => it.deletedAt == null && it.kind === "task")
    .map((it) => it as Task)
    .filter((t) => !t.completedAt) // open
    .filter((t) => t.pinnedToToday || t.dueDate === todayKey) // v1: you can simplify
    .map((t) => t.id);
}

export function deriveCompletedTodayIds(items: Item[], todayKey: string) {
  return items
    .filter((it) => it.deletedAt == null && it.kind === "task")
    .map((it) => it as Task)
    .filter((t) => t.completedAt && dayKey(t.completedAt) === todayKey)
    .map((t) => t.id);
}

export function deriveRecentIds(items: Item[], now: number, days = 7) {
  const windowStart = now - days * 24 * 3600 * 1000;
  return items
    .filter((it) => it.deletedAt == null)
    .filter((it) => it.createdAt >= windowStart && it.createdAt <= now)
    .sort((a, b) => b.createdAt - a.createdAt)
    .map((it) => it.id);
}

export function groupRecentByCreatedDay(itemsById: Map<string, Item>, recentIds: string[]) {
  const groups = new Map<string, string[]>(); // dayKey -> ids
  for (const id of recentIds) {
    const it = itemsById.get(id);
    if (!it) continue;
    const key = dayKey(it.createdAt);
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key)!.push(id);
  }
  return Array.from(groups.entries())
    .sort((a, b) => (a[0] < b[0] ? 1 : -1)); // newest day first
}

export function countRecent(items: Item[], now: number, days = 7) {
  const windowStart = now - days * 24 * 3600 * 1000;
  const added = items.filter(it => it.deletedAt == null && it.createdAt >= windowStart && it.createdAt <= now).length;
  const completed = items.filter(it => it.deletedAt == null && it.kind === "task" && (it as any).completedAt
    && (it as any).completedAt >= windowStart && (it as any).completedAt <= now).length;
  return { added, completed };
}
```

