## IndexedDB storage (local-only)

### `db/db.ts`
```ts
import { openDB } from "idb";
import { Item } from "../model/types";

export const dbPromise = openDB("today-app", 1, {
  upgrade(db) {
    const store = db.createObjectStore("items", { keyPath: "id" });
    store.createIndex("createdAt", "createdAt");
  },
});

export async function loadAllItems(): Promise<Item[]> {
  const db = await dbPromise;
  return (await db.getAll("items")) as Item[];
}

export async function putItem(item: Item) {
  const db = await dbPromise;
  await db.put("items", item);
}

export async function putItems(items: Item[]) {
  const db = await dbPromise;
  const tx = db.transaction("items", "readwrite");
  for (const it of items) tx.store.put(it);
  await tx.done;
}
```

