## Global key bindings (Ctrl/Cmd+K, Esc)

### `app/useGlobalKeys.ts`
```ts
import { RefObject, useEffect } from "react";

function isTextInput(el: EventTarget | null) {
  const e = el as HTMLElement | null;
  if (!e) return false;
  const tag = e.tagName?.toLowerCase();
  return tag === "input" || tag === "textarea" || e.isContentEditable;
}

export function useGlobalKeys(opts: {
  captureRef: RefObject<HTMLInputElement>;
  clearCapture: () => void;
  hasCaptureText: () => boolean;
  collapsePanels: () => void;
}) {
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      const key = e.key.toLowerCase();
      const mod = e.metaKey || e.ctrlKey;

      if (mod && key === "k") {
        e.preventDefault();
        opts.captureRef.current?.focus();
        return;
      }

      if (key === "escape") {
        // Let Escape in text inputs clear capture only if capture is focused;
        // otherwise treat as global collapse.
        if (opts.hasCaptureText()) {
          opts.clearCapture();
          return;
        }
        // avoid hijacking Esc inside other editors
        if (isTextInput(e.target)) return;

        opts.collapsePanels();
      }
    };

    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [opts]);
}
```

