## Today list: row keydown (Up/Down/Space/x)

### `ui/TodayList.tsx`
```tsx
import React, { useEffect, useMemo, useRef, useState } from "react";
import { Item } from "../model/types";
import { TaskRow } from "./TaskRow";

export function TodayList(props: {
  todayIds: string[];
  completedTodayIds: string[];
  itemsById: Map<string, Item>;
  onToggleComplete: (id: string) => void | Promise<void>;
  onDelete: (id: string) => void | Promise<void>;
}) {
  const [focusIndex, setFocusIndex] = useState(0);
  const rowRefs = useRef<Array<HTMLDivElement | null>>([]);

  // Keep focusIndex in range as list changes.
  useEffect(() => {
    if (props.todayIds.length === 0) setFocusIndex(0);
    else if (focusIndex > props.todayIds.length - 1) setFocusIndex(props.todayIds.length - 1);
  }, [props.todayIds.length, focusIndex]);

  const focusRow = (i: number) => {
    const clamped = Math.max(0, Math.min(i, props.todayIds.length - 1));
    setFocusIndex(clamped);
    rowRefs.current[clamped]?.focus();
  };

  return (
    <section aria-label="Today">
      <h2>Today</h2>

      <div role="list">
        {props.todayIds.map((id, i) => {
          const it = props.itemsById.get(id);
          if (!it || it.kind !== "task") return null;

          return (
            <TaskRow
              key={id}
              ref={(el) => { rowRefs.current[i] = el; }}
              task={it}
              tabIndex={i === focusIndex ? 0 : -1}
              onToggleComplete={() => props.onToggleComplete(id)}
              onDelete={() => props.onDelete(id)}
              onKeyDown={(e) => {
                if (e.key === "ArrowDown") { e.preventDefault(); focusRow(i + 1); }
                else if (e.key === "ArrowUp") { e.preventDefault(); focusRow(i - 1); }
                else if (e.key === " ") { e.preventDefault(); props.onToggleComplete(id); }
                else if (e.key.toLowerCase() === "x") { e.preventDefault(); props.onDelete(id); }
              }}
              onFocus={() => setFocusIndex(i)}
            />
          );
        })}
      </div>

      {props.completedTodayIds.length > 0 && (
        <details>
          <summary>Completed today ({props.completedTodayIds.length})</summary>
          <ul>
            {props.completedTodayIds.map((id) => {
              const it = props.itemsById.get(id);
              if (!it || it.kind !== "task") return null;
              return <li key={id}>{it.text}</li>;
            })}
          </ul>
        </details>
      )}
    </section>
  );
}
```

